namespace {
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
class Original final:public H8SEmulator{public:int readHistory()const{return lastread;}int writeHistory()const{return lastwrite;}int irqDepth()const{return indent;}void histories(int r,int w){lastread=r;lastwrite=w;}void irqDepth(int d){indent=d;}};
using C=kstation::Stage1Cpu;
struct Event{uint64_t clocks;unsigned pc,at;std::array<int32_t,8>regs;uint8_t flags,exr,value;bool write;};
template<class Cpu>class Bus final:public H8SDevice{public:Cpu&c;unsigned count=0,command=0,remaining=0,pageWrites=0,lcdReads=0,lcdBusy=0,lastReads=0,stallReads=0;bool dropLast=false;unsigned dropIndex=~0u;uint32_t page=0,tick=0;std::array<Event,8>events{};explicit Bus(Cpu&p):c(p){}void record(unsigned at,uint8_t v,bool w){check(count<events.size(),"IO overflow");auto&e=events[count++];e={c.cycles,unsigned(c.getPC()),at,{},c.ccr,c.exr,v,w};for(unsigned j=0;j<8;++j)e.regs[j]=c.regs[j].er;}uint8_t read(unsigned at)override{uint8_t v=c.memory[at];if(at==0x600004)v=uint8_t(6|(c.memory[0x600000]&8?16:0));if(at>=0xfffd20&&at<=0xfffd23){if(at==0xfffd20)tick=uint32_t(c.cycles/1000);v=uint8_t(tick>>((0xfffd23-at)*8));}if(at==0xffffc7)v=lcdReads++<lcdBusy?0x80:0;if(pageWrites==256&&at==page+255&&lastReads++<stallReads)v^=1;record(at,v,false);return v;}
 void write(unsigned at,uint8_t v)override{record(at,v,true);if(at>=0x200000&&at<0x240000){auto offset=at-0x200000;if(command==3){if(!pageWrites)page=at;if((!dropLast||remaining!=1)&&pageWrites!=dropIndex)c.memory[at]=v;++pageWrites;if(!--remaining)command=0;return;}if(command==0&&offset==0x5555&&v==0xaa)command=1;else if(command==1&&offset==0x2aaa&&v==0x55)command=2;else if(command==2&&offset==0x5555&&v==0xa0){command=3;remaining=256;}else command=0;return;}c.memory[at]=v;}
};
struct F {std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<C>b=std::make_unique<C>();Bus<Original>x{*a};Bus<C>y{*b};uint64_t graphs=0,phases=0,events=0,programs=0;explicit F(const std::vector<uint8_t>&rom){a->loadmem(rom.data(),rom.size(),0);b->loadmem(rom.data(),rom.size(),0);for(auto q:{std::pair{0x200000,0x40000},std::pair{0xfffd00,0x300},std::pair{0xba00,0x200},std::pair{0xcb00,0x300},std::pair{0xce00,0x400},std::pair{0x600000,16}}){a->memmap(&x,q.first,q.second);b->memmap(&y,q.first,q.second);}}void byte(unsigned at,unsigned v){a->memory[at&0xffffff]=b->memory[at&0xffffff]=uint8_t(v);}void word(unsigned at,unsigned v){byte(at,v>>8);byte(at+1,v);}void wide(unsigned at,unsigned v){word(at,v>>16);word(at+2,v);}void equal(unsigned at){bool ok=a->cycles==b->cycles&&a->getPC()==b->getPC()&&a->ccr==b->ccr&&a->exr==b->exr&&a->readHistory()==b->readHistory()&&a->writeHistory()==b->writeHistory()&&a->irqDepth()==b->irqDepth()&&x.count==y.count;for(unsigned i=0;i<8;++i)ok&=a->regs[i].er==b->regs[i].er;for(unsigned i=0;i<x.count&&i<y.count;++i){auto&p=x.events[i];auto&q=y.events[i];ok&=p.clocks==q.clocks&&p.pc==q.pc&&p.at==q.at&&p.regs==q.regs&&p.flags==q.flags&&p.exr==q.exr&&p.value==q.value&&p.write==q.write;}if(!ok){std::fprintf(stderr,"mismatch at %x next %x/%x cycles %llu/%llu events %u/%u\n",at,a->getPC(),b->getPC(),a->cycles,b->cycles,x.count,y.count);throw std::runtime_error("flash owner mismatch");}events+=x.count;x.count=y.count=0;}
 void global(unsigned flags){for(unsigned i=0;i<8;++i)a->regs[i].er=b->regs[i].er=int32_t(0x9a6c0011+i*0x122334);a->pc=a->makepc(0x4e3c);b->pc=b->makepc(0x4e3c);a->setSP(0xffff00);b->setSP(0xffff00);wide(0xffff00,0x7000);a->reg32(1)=b->reg32(1)=0xcc0c;a->cycles=b->cycles=100000;a->ccr=b->ccr=uint8_t(flags);a->exr=b->exr=0x5a;a->pending_irqs=b->pending_irqs=0;a->pending_irqs_high=b->pending_irqs_high=0;a->interruptMode2=b->interruptMode2=false;a->histories(0x200001,0xfffe6f);b->histories(0x200001,0xfffe6f);a->irqDepth(3);b->irqDepth(3);x.command=y.command=x.remaining=y.remaining=x.pageWrites=y.pageWrites=0;x.count=y.count=0;byte(0xbb14,1);std::array<uint8_t,256> expected{};for(unsigned i=0;i<256;++i){expected[i]=uint8_t(i*73+19);byte(0xcc0c+i,expected[i]);byte(0x21ff00+i,uint8_t(i*13+7));}kstation::NativeFlashCommitOwner owner;kstation::NativeFlashState flash;check(owner.admit(*b,0x7000),"global owner admit");unsigned n=0;while(uint32_t(a->getPC())!=0x7000||owner.active()||flash.active()){check(++n<100000,"global graph hang");unsigned at=uint32_t(a->getPC());bool stepped=(flash.active()||at==0x4d96||at==0x5556)?flash.step(*b):owner.step(*b);if(!stepped){equal(at);check(uint32_t(a->getPC())==0x7000&&!owner.active()&&!flash.active(),"global missing native child");break;}a->step();equal(at);++phases;}check(x.pageWrites==256&&y.pageWrites==256,"global program not reached");check(!std::memcmp(a->memory+0x21ff00,b->memory+0x21ff00,256),"global flash divergence");check(!std::memcmp(a->memory+0x21ff00,expected.data(),256),"global flash bytes");check(!std::memcmp(a->memory+0xbb12,expected.data(),23),"global loaded bytes");++graphs;++programs;}
 void run(unsigned flags,bool patch,unsigned bank,unsigned number){for(unsigned i=0;i<8;++i)a->regs[i].er=b->regs[i].er=int32_t(0x9a6c0011+i*0x122334);a->pc=a->makepc(patch?0x4d3a:0x4e10);b->pc=b->makepc(patch?0x4d3a:0x4e10);a->setSP(0xffff00);b->setSP(0xffff00);wide(0xffff00,0x7000);a->reg32(0)=b->reg32(0)=0xcd14;a->reg32(1)=b->reg32(1)=0xcc0c;a->cycles=b->cycles=100000;a->ccr=b->ccr=uint8_t(flags);a->exr=b->exr=0x5a;a->pending_irqs=b->pending_irqs=0;a->pending_irqs_high=b->pending_irqs_high=0;a->interruptMode2=b->interruptMode2=false;a->histories(0x200001,0xfffe6f);b->histories(0x200001,0xfffe6f);a->irqDepth(3);b->irqDepth(3);x.command=y.command=x.remaining=y.remaining=x.pageWrites=y.pageWrites=0;x.count=y.count=0;byte(0xcd14,bank);byte(0xcd15,number);byte(0xbb14,1);auto index=(bank-1)*100+number;uint32_t page=(0x226400+index*128)&~255u;std::array<uint8_t,256> expected{};for(unsigned i=0;i<256;++i){byte(page+i,uint8_t(i*13+7));byte(0xcc0c+i,uint8_t(i*73+19));expected[i]=uint8_t(i*13+7);}if(patch)for(unsigned i=0;i<128;++i)expected[(index&1)*128+i]=uint8_t(i*73+19);else for(unsigned i=0;i<256;++i)expected[i]=uint8_t(i*73+19);kstation::NativeFlashCommitOwner owner;kstation::NativeProgramState indexer;kstation::NativeFlashState flash;check(owner.admit(*b,0x7000),"owner admit");unsigned n=0;while(uint32_t(a->getPC())!=0x7000||owner.active()||indexer.active()||flash.active()){check(++n<100000,"flash graph hang");unsigned at=uint32_t(a->getPC());bool stepped=false;if(indexer.active()||at==0x4c36)stepped=indexer.step(*b);else if(flash.active()||at==0x4d96)stepped=flash.step(*b);else stepped=owner.step(*b);if(!stepped){equal(at);check(uint32_t(a->getPC())==0x7000&&!owner.active()&&!indexer.active()&&!flash.active(),"missing native child");break;}a->step();equal(at);++phases;}check(x.pageWrites==256&&y.pageWrites==256,"page program not reached");check(!std::memcmp(a->memory+page,b->memory+page,256),"flash divergence");check(!std::memcmp(a->memory+page,expected.data(),256),"flash page contents");++graphs;++programs;}
};}
int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"ROM size");F f(rom);for(unsigned flags:{0u,0x2fu,0x80u,0xffu})f.global(flags);for(unsigned flags:{0u,0x2fu,0x80u,0xffu})for(bool patch:{false,true})for(unsigned number:{0u,2u,98u})f.run(flags,patch,1,number);for(unsigned flags:{0u,0x80u})for(unsigned number:{1u,99u})f.run(flags,true,4,number);std::printf("{\"passed\":true,\"graphs\":%llu,\"native_phases\":%llu,\"ordered_bus_events\":%llu,\"actual_page_programs\":%llu}\n",(unsigned long long)f.graphs,(unsigned long long)f.phases,(unsigned long long)f.events,(unsigned long long)f.programs);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL: %s\n",e.what());return 1;}}
